import datetime
import math
from collections import defaultdict

import openpyxl


SOURCE_PATH = '/root/Maintenance_Parts_and_Deliveries_Latest.xlsx'
OUTPUT_PATH = '/root/maintenance_resupply_actions_sep_2025.xlsx'


def _to_date(v):
    """Convert openpyxl cell value into datetime.date (or None).

    Accepts datetime.date, datetime.datetime, or ISO 'YYYY-MM-DD' strings.
    """
    if v is None:
        return None
    if isinstance(v, datetime.datetime):
        return v.date()
    if isinstance(v, datetime.date):
        return v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        # Expect ISO format per source inspection.
        return datetime.date.fromisoformat(s)
    raise TypeError(f'Unsupported date value type: {type(v).__name__} ({v!r})')


def _to_number(v):
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return v
    # Sometimes numbers are stored as strings in Excel.
    if isinstance(v, str):
        s = v.strip()
        if s == '':
            return None
        if '.' in s:
            return float(s)
        return int(s)
    raise TypeError(f'Unsupported numeric value type: {type(v).__name__} ({v!r})')


def read_current_parts(wb):
    ws = wb['Current Parts']

    as_of_date = _to_date(ws['B1'].value)
    planning_end = _to_date(ws['D1'].value)

    # Header row is row 3 per inspection.
    header_row = 3
    headers = {}
    for c in range(1, ws.max_column + 1):
        v = ws.cell(row=header_row, column=c).value
        if isinstance(v, str) and v.strip():
            headers[v.strip()] = c

    required = ['Part_Code', 'Current_Units', 'Daily_Consumption_Units']
    missing = [h for h in required if h not in headers]
    if missing:
        raise ValueError(f"Missing required columns in 'Current Parts': {missing}. Found: {sorted(headers.keys())}")

    parts = []
    for r in range(header_row + 1, ws.max_row + 1):
        part_code = ws.cell(row=r, column=headers['Part_Code']).value
        if part_code is None or (isinstance(part_code, str) and not part_code.strip()):
            continue
        part_code = str(part_code).strip()

        current_units = _to_number(ws.cell(row=r, column=headers['Current_Units']).value)
        daily = _to_number(ws.cell(row=r, column=headers['Daily_Consumption_Units']).value)

        parts.append(
            {
                'Part_Code': part_code,
                'Current_Units': current_units,
                'Daily_Consumption_Units': daily,
            }
        )

    return as_of_date, planning_end, parts


def read_scheduled_deliveries(wb):
    ws = wb['Scheduled Deliveries']

    # Header row is row 1 per inspection.
    header_row = 1
    headers = {}
    for c in range(1, ws.max_column + 1):
        v = ws.cell(row=header_row, column=c).value
        if isinstance(v, str) and v.strip():
            headers[v.strip()] = c

    required = ['Part_Code', 'Delivery Date', 'Units']
    missing = [h for h in required if h not in headers]
    if missing:
        raise ValueError(
            f"Missing required columns in 'Scheduled Deliveries': {missing}. Found: {sorted(headers.keys())}"
        )

    deliveries = defaultdict(list)  # part_code -> list[(date, units)]
    for r in range(header_row + 1, ws.max_row + 1):
        part_code = ws.cell(row=r, column=headers['Part_Code']).value
        if part_code is None or (isinstance(part_code, str) and not part_code.strip()):
            continue
        part_code = str(part_code).strip()

        d = _to_date(ws.cell(row=r, column=headers['Delivery Date']).value)
        units = _to_number(ws.cell(row=r, column=headers['Units']).value)

        if d is None or units is None:
            continue

        deliveries[part_code].append((d, units))

    # Keep stable ordering within each part by sorting by date.
    for k in list(deliveries.keys()):
        deliveries[k].sort(key=lambda t: t[0])

    return deliveries


def read_ratios(wb):
    ws = wb['Ratio']

    # Two supported structures:
    # 1) Global ratio: header 'Units_Per_Crate' in A1 and value in A2.
    # 2) Per-part ratio: header row includes 'Part_Code' and 'Units_Per_Crate'.

    # Build header map from row 1.
    header_row = 1
    headers = {}
    for c in range(1, ws.max_column + 1):
        v = ws.cell(row=header_row, column=c).value
        if isinstance(v, str) and v.strip():
            headers[v.strip()] = c

    if 'Part_Code' in headers and 'Units_Per_Crate' in headers:
        ratio_by_part = {}
        for r in range(header_row + 1, ws.max_row + 1):
            part_code = ws.cell(row=r, column=headers['Part_Code']).value
            if part_code is None or (isinstance(part_code, str) and not part_code.strip()):
                continue
            part_code = str(part_code).strip()
            ratio = _to_number(ws.cell(row=r, column=headers['Units_Per_Crate']).value)
            if ratio is None:
                continue
            ratio_by_part[part_code] = ratio
        if not ratio_by_part:
            raise ValueError("'Ratio' sheet has per-part structure but no ratios were read")
        return ratio_by_part, None

    # Global structure.
    if ws.max_row >= 2 and ws.max_column >= 1:
        header = ws['A1'].value
        if isinstance(header, str) and header.strip() == 'Units_Per_Crate':
            global_ratio = _to_number(ws['A2'].value)
            if global_ratio is None:
                raise ValueError("Global 'Units_Per_Crate' found in Ratio sheet, but A2 is blank")
            return {}, global_ratio

    raise ValueError(
        "Unrecognized 'Ratio' sheet structure. Expected either a global Units_Per_Crate in A1/A2 "
        "or columns Part_Code and Units_Per_Crate."
    )


def compute_results(parts, deliveries_by_part, ratio_by_part, global_ratio, as_of_date, planning_end):
    remaining_days = (planning_end - as_of_date).days

    results = []
    for p in parts:
        part_code = p['Part_Code']
        current_units = p['Current_Units']
        daily = p['Daily_Consumption_Units']

        # Crate ratio
        if part_code in ratio_by_part:
            ratio = ratio_by_part[part_code]
        else:
            ratio = global_ratio
        if ratio is None:
            raise ValueError(f"No Units_Per_Crate ratio available for part {part_code}")

        # Current_DOH
        if daily is not None and daily > 0:
            current_doh = current_units / daily if current_units is not None else None
        else:
            current_doh = None

        # Projected_Stockout_Date
        if daily is not None and daily > 0 and current_doh is not None:
            projected_stockout = as_of_date + datetime.timedelta(days=math.floor(current_doh))
        else:
            projected_stockout = None

        # Inbound_Units_By_Sep30
        inbound = 0
        for (d, qty) in deliveries_by_part.get(part_code, []):
            if d <= planning_end:
                inbound += qty

        # Delivered_DOH_To_Sep30
        if daily is not None and daily > 0 and current_units is not None:
            delivered_doh = (current_units + inbound) / daily
        else:
            delivered_doh = None

        # Remaining_September_Demand_Units
        remaining_demand = daily * remaining_days if daily is not None else None

        # Additional_Units_Needed
        if remaining_demand is None or current_units is None:
            additional = None
        else:
            additional = max(0, remaining_demand - current_units - inbound)

        # Crates_Required_Rounded_Up
        raw_crates = None
        if additional is not None and additional > 0:
            raw_crates = additional / ratio
            crates = math.ceil(raw_crates)
        else:
            crates = 0

        # Earliest_Scheduled_Delivery_Date
        ds = deliveries_by_part.get(part_code, [])
        if ds:
            earliest_del = min(d for (d, _q) in ds)
        else:
            earliest_del = None

        # Required_Delivery_Date
        if crates == 0:
            req_date = None
        elif earliest_del is not None and projected_stockout is not None and earliest_del <= projected_stockout:
            # delivered_doh should be non-None here given daily>0, but guard anyway.
            if delivered_doh is None:
                req_date = None
            else:
                req_date = as_of_date + datetime.timedelta(days=math.floor(delivered_doh))
        else:
            req_date = projected_stockout

        # Rounding_Applied
        if additional is not None and additional > 0:
            rounding = (math.ceil(additional / ratio) != (additional / ratio))
        else:
            rounding = False

        # Earlier_Delivery_Required
        if crates > 0 and (earliest_del is None or (req_date is not None and req_date < earliest_del)):
            earlier = True
        else:
            earlier = False

        results.append(
            {
                'Part_Code': part_code,
                'Current_Units': current_units,
                'Daily_Consumption_Units': daily,
                'Current_DOH': current_doh,
                'Projected_Stockout_Date': str(projected_stockout) if projected_stockout is not None else None,
                'Inbound_Units_By_Sep30': inbound,
                'Delivered_DOH_To_Sep30': delivered_doh,
                'Remaining_September_Demand_Units': remaining_demand,
                'Additional_Units_Needed': additional,
                'Crates_Required_Rounded_Up': crates,
                'Earliest_Scheduled_Delivery_Date': str(earliest_del) if earliest_del is not None else None,
                'Required_Delivery_Date': str(req_date) if req_date is not None else None,
                'Rounding_Applied': bool(rounding),
                'Earlier_Delivery_Required': bool(earlier),
            }
        )

    return remaining_days, results


def write_output(as_of_date, planning_end, remaining_days, results):
    wb_out = openpyxl.Workbook()

    # Replace default sheet with the required first sheet.
    default = wb_out.active
    default.title = 'Part_Results'
    ws1 = default

    # Sheet 2
    ws2 = wb_out.create_sheet('Additional_Resupply_Needed')

    # --- Sheet 1: metadata ---
    ws1['A1'].value = 'Field'
    ws1['B1'].value = 'Value'

    ws1['A2'].value = 'AsOfDate'
    ws1['B2'].value = str(as_of_date) if as_of_date is not None else None

    ws1['A3'].value = 'PlanningHorizonEnd'
    ws1['B3'].value = str(planning_end) if planning_end is not None else None

    ws1['A4'].value = 'RemainingDaysInSeptember'
    ws1['B4'].value = int(remaining_days)

    # --- Sheet 1: header ---
    headers = [
        'Part_Code',
        'Current_Units',
        'Daily_Consumption_Units',
        'Current_DOH',
        'Projected_Stockout_Date',
        'Inbound_Units_By_Sep30',
        'Delivered_DOH_To_Sep30',
        'Remaining_September_Demand_Units',
        'Additional_Units_Needed',
        'Crates_Required_Rounded_Up',
        'Earliest_Scheduled_Delivery_Date',
        'Required_Delivery_Date',
        'Rounding_Applied',
        'Earlier_Delivery_Required',
    ]

    header_row = 6
    for c, h in enumerate(headers, start=1):
        ws1.cell(row=header_row, column=c).value = h

    # --- Sheet 1: data ---
    start_row = 7
    for i, row in enumerate(results):
        r = start_row + i
        for c, h in enumerate(headers, start=1):
            ws1.cell(row=r, column=c).value = row.get(h)

    # --- Sheet 2: filtered ---
    headers2 = [
        'Part_Code',
        'Additional_Units_Needed',
        'Crates_Required_Rounded_Up',
        'Required_Delivery_Date',
        'Earliest_Scheduled_Delivery_Date',
        'Earlier_Delivery_Required',
    ]

    for c, h in enumerate(headers2, start=1):
        ws2.cell(row=1, column=c).value = h

    out_r = 2
    for row in results:
        crates = row.get('Crates_Required_Rounded_Up')
        if crates is None or crates <= 0:
            continue
        for c, h in enumerate(headers2, start=1):
            ws2.cell(row=out_r, column=c).value = row.get(h)
        out_r += 1

    wb_out.save(OUTPUT_PATH)


def main():
    wb = openpyxl.load_workbook(SOURCE_PATH, data_only=True)

    as_of_date, planning_end, parts = read_current_parts(wb)
    if as_of_date is None or planning_end is None:
        raise ValueError('AsOfDate and/or PlanningHorizonEnd is blank in Current Parts sheet')

    deliveries_by_part = read_scheduled_deliveries(wb)
    ratio_by_part, global_ratio = read_ratios(wb)

    remaining_days, results = compute_results(
        parts=parts,
        deliveries_by_part=deliveries_by_part,
        ratio_by_part=ratio_by_part,
        global_ratio=global_ratio,
        as_of_date=as_of_date,
        planning_end=planning_end,
    )

    write_output(
        as_of_date=as_of_date,
        planning_end=planning_end,
        remaining_days=remaining_days,
        results=results,
    )


if __name__ == '__main__':
    main()
PY
